/**
 * The bundled four-room LAN default layouts (generated by
 * scripts/generate-lan-layout.mjs — the shared office and `--personal`): every
 * room is labelled, has enough seats, and is reachable on foot from every other room.
 *
 * Run with: npm test
 */

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, test } from 'vitest';

import { buildFurnitureCatalog } from '../../core/src/assets/build.ts';
import { decodeAllFurniture } from '../../core/src/assets/loader.ts';
import { OfficeState } from '../src/office/engine/officeState.js';
import { buildDynamicCatalog } from '../src/office/layout/furnitureCatalog.js';
import { findPath, isWalkable } from '../src/office/layout/tileMap.js';
import type { OfficeLayout } from '../src/office/types.js';
import { MAX_COLS, MAX_ROWS } from '../src/office/types.js';

const assetsDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../public/assets');
const catalog = buildFurnitureCatalog(assetsDir);
buildDynamicCatalog({ catalog, sprites: decodeAllFurniture(assetsDir, catalog) });

const ROOMS = ['코딩실', '자료실', '서버실', '대기실'];
const VARIANTS = [
  {
    file: 'default-layout-1.json',
    args: [],
    size: { minCols: 80, maxCols: 128, minRows: 50, maxRows: 128 },
    seats: { 코딩실: [60, 999], 자료실: [40, 999], 서버실: [40, 999], 대기실: [80, 999] },
  },
  {
    // A personal office: one person and a handful of agents.
    file: 'default-layout-personal.json',
    args: ['--personal'],
    size: { minCols: 26, maxCols: 36, minRows: 18, maxRows: 24 },
    seats: { 코딩실: [6, 10], 자료실: [6, 10], 서버실: [6, 10], 대기실: [6, 10] },
  },
] as const;

describe.each(VARIANTS)('$file', ({ file, args, size, seats }) => {
  const raw = fs.readFileSync(path.join(assetsDir, file), 'utf-8');
  const layout = JSON.parse(raw) as OfficeLayout;
  const os = new OfficeState(layout);

  /** Walkable tiles of a room (by area label). */
  function roomTiles(label: string): Array<{ col: number; row: number }> {
    return os.walkableTiles.filter(
      (t) => layout.areaTiles?.[t.row * layout.cols + t.col] === label,
    );
  }

  test('is what the generator writes (deterministic)', () => {
    const script = path.resolve(assetsDir, '../../../scripts/generate-lan-layout.mjs');
    assert.equal(execFileSync(process.execPath, [script, ...args], { encoding: 'utf-8' }), raw);
  });

  test('fits its size range and defines exactly the four rooms', () => {
    assert.ok(layout.cols <= MAX_COLS && layout.rows <= MAX_ROWS);
    const { cols, rows } = layout;
    assert.ok(cols >= size.minCols && cols <= size.maxCols, `${cols}×${rows}`);
    assert.ok(rows >= size.minRows && rows <= size.maxRows, `${cols}×${rows}`);
    assert.deepEqual(
      (layout.areas ?? []).map((a) => a.label),
      ROOMS,
    );
    for (const a of layout.areas ?? []) assert.match(a.color, /^#[0-9a-f]{6}$/i);
    for (const label of ROOMS) assert.ok(roomTiles(label).length > 0, `${label} has open floor`);
  });

  test('every furniture type exists in the bundled catalog', () => {
    const ids = new Set(catalog.map((c) => c.id));
    for (const f of layout.furniture) assert.ok(ids.has(f.type.replace(/:left$/, '')), f.type);
  });

  test('each room has its seat range', () => {
    const counts: Record<string, number> = {};
    for (const uid of os.seats.keys()) {
      const zone = os.seatZone(uid);
      if (zone) counts[zone] = (counts[zone] ?? 0) + 1;
    }
    for (const label of ROOMS) {
      const n = counts[label] ?? 0;
      const [min, max] = seats[label as keyof typeof seats];
      assert.ok(n >= min && n <= max, `${label}: ${n} seats`);
    }
  });

  test('every room is reachable on foot from every other room', () => {
    for (const from of ROOMS) {
      const start = roomTiles(from)[0];
      for (const to of ROOMS) {
        if (to === from) continue;
        const end = roomTiles(to)[0];
        const p = findPath(start.col, start.row, end.col, end.row, os.tileMap, os.blockedTiles);
        assert.ok(p.length > 0, `${from} → ${to}`);
      }
    }
  });

  test('every seat can be walked to', () => {
    const start = roomTiles('대기실')[0];
    for (const seat of os.seats.values()) {
      const reachable = [
        [0, -1],
        [0, 1],
        [-1, 0],
        [1, 0],
      ].some(([dc, dr]) => {
        const c = seat.seatCol + dc;
        const r = seat.seatRow + dr;
        if (!isWalkable(c, r, os.tileMap, os.blockedTiles)) return false;
        return (
          (c === start.col && r === start.row) ||
          findPath(start.col, start.row, c, r, os.tileMap, os.blockedTiles).length > 0
        );
      });
      assert.ok(reachable, `seat ${seat.uid} at ${seat.seatCol},${seat.seatRow}`);
    }
  });
});
